import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long input = Long.parseLong(br.readLine());
        System.out.println(countOnes(input));
    }

    private static int getDigitsCount(long n) {
        return (int) Math.log10(n) + 1;
    }

    private static long generateSequence(int length) {
        long val = 1;
        for (int i = 1; i < length; i++) {
            val = val * 10 + 1;
        }
        return val;
    }

    private static long countOnes(long n) {
        if (n <= 6) return n;
        int digits = getDigitsCount(n);
        long baseSeq = generateSequence(digits);
        long sumSeq = baseSeq;
        int count = 0;
        long diff = n;

        while (sumSeq < n) {
            count++;
            diff = n - sumSeq;
            sumSeq += generateSequence(digits);
        }

        long res;
        if (count > 0)
            res = Math.min(count * digits + countOnes(diff),
                           (count + 1) * digits + countOnes(sumSeq - n));
        else
            res = (count + 1) * digits + countOnes(sumSeq - n);

        long nextSeq = generateSequence(digits + 1);
        if (nextSeq - n < n)
            res = Math.min(res, digits + 1 + countOnes(nextSeq - n));
        return res;
    }
}
